#include <RCSwitch.h>
RCSwitch sw = RCSwitch();
void setup() {
    Serial.begin(115200);
    sw.enableReceive(digitalPinToInterrupt({{rx_pin}}));
}
void loop() {
    if (sw.available()) {
        Serial.printf("code=%lu bits=%u\n", sw.getReceivedValue(), sw.getReceivedBitlength());
        sw.resetAvailable();
    }
}
